//! TerraSol SP1 Verifier for Solana.
//!
//! Verifies Groth16 proofs produced by SP1 6.8.x (Groth16 circuit v6.1.0) directly on Solana,
//! using the `alt_bn128` syscalls through `groth16-solana`. The Groth16 verifying key is stored
//! in uncompressed form (see `vk.rs`, generated by `vkgen`), so no point decompression runs
//! on-chain. Measured on Solana devnet: 104,874 compute units per verification.
//!
//! Two layers:
//! - [`verify_sp1_groth16`]: generic check for any SP1 program (pass its verifying-key hash).
//! - [`verify_chain_proof`]: the deployed program. It accepts proofs of exactly one SP1 program
//!   (`vk::PROGRAM_VKEY_HASH`) whose public values are a 188-byte [`ChainSummary`].
//!
//! Instruction data of the deployed program: proof (356 bytes, exactly
//! `SP1ProofWithPublicValues::bytes()`) followed by the public values (188 bytes).
#![allow(unexpected_cfgs)]

use groth16_solana::groth16::{Groth16Verifier, Groth16Verifyingkey};

pub mod vk;

/// Length of an SP1 Groth16 proof: 4 (verifying-key prefix) + 3 × 32 (exit_code, vk_root, nonce) + 256.
pub const PROOF_LEN: usize = 356;
/// Length of the public values of the chain program (`ChainSummary`, bincode, little-endian).
pub const CHAIN_VALUES_LEN: usize = 188;

/// Base field modulus of BN254 (used to negate point A).
const Q: [u8; 32] = [
    0x30, 0x64, 0x4e, 0x72, 0xe1, 0x31, 0xa0, 0x29, 0xb8, 0x50, 0x45, 0xb6, 0x81, 0x81, 0x58, 0x5d, 0x97, 0x81, 0x6a,
    0x91, 0x68, 0x71, 0xca, 0x8d, 0x3c, 0x20, 0x8c, 0x16, 0xd8, 0x7c, 0xfd, 0x47,
];

/// Error codes (also returned as `ProgramError::Custom` by the program).
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum Error {
    Length = 1,
    VkPrefix = 2,
    ExitCode = 3,
    VkRoot = 4,
    Proof = 5,
}

/// What a valid chain proof states (decoded from its public values).
#[derive(Debug, PartialEq, Eq)]
pub struct ChainSummary {
    /// Verifying-key hash of the SP1 program that proved each block
    pub block_vkey: [u8; 32],
    /// State commitment at the start of the chain
    pub start: [u8; 32],
    /// State commitment at the end of the chain
    pub end: [u8; 32],
    /// Number of blocks in the chain
    pub blocks: u32,
    /// Hash over all inputs of all blocks
    pub inputs_hash: [u8; 32],
    /// Hash over all results of all blocks
    pub results_hash: [u8; 32],
    /// Number of inputs (orders)
    pub inputs: u64,
    /// Number of results (fills)
    pub results: u64,
    /// Total volume
    pub volume: u64,
}

fn sha256(b: &[u8]) -> [u8; 32] {
    solana_program::hash::hashv(&[b]).to_bytes()
}

/// y → q − y (negate point A, as required by the pairing check in groth16-solana).
fn negate(y: &[u8]) -> [u8; 32] {
    let mut r = [0u8; 32];
    if y.iter().all(|&b| b == 0) {
        return r;
    }
    let mut borrow = 0i16;
    for i in (0..32).rev() {
        let mut d = Q[i] as i16 - y[i] as i16 - borrow;
        borrow = if d < 0 {
            d += 256;
            1
        } else {
            0
        };
        r[i] = d as u8;
    }
    r
}

fn field<const N: usize>(b: &[u8], from: usize) -> [u8; N] {
    b[from..from + N].try_into().unwrap()
}

/// Verifies an SP1 v6 Groth16 proof for the SP1 program with verifying-key hash
/// `program_vkey_hash` (`vk.bytes32()`) and the given public values.
/// No Solana accounts involved, so it also runs natively (tests, off-chain tools).
pub fn verify_sp1_groth16(proof: &[u8], public_values: &[u8], program_vkey_hash: &[u8; 32]) -> Result<(), Error> {
    if proof.len() != PROOF_LEN {
        return Err(Error::Length);
    }
    if proof[..4] != vk::GROTH16_VK_PREFIX {
        return Err(Error::VkPrefix);
    }
    let exit_code: [u8; 32] = field(proof, 4);
    let vk_root: [u8; 32] = field(proof, 36);
    let nonce: [u8; 32] = field(proof, 68);
    if exit_code != [0u8; 32] {
        return Err(Error::ExitCode);
    }
    if vk_root != vk::VK_ROOT {
        return Err(Error::VkRoot);
    }

    let p = &proof[100..];
    let mut a: [u8; 64] = field(p, 0);
    let y = negate(&a[32..64]);
    a[32..64].copy_from_slice(&y);
    let b: [u8; 128] = field(p, 64);
    let c: [u8; 64] = field(p, 192);

    // Digest of the public values as in SP1: SHA-256 with the top 3 bits cleared
    let mut digest = sha256(public_values);
    digest[0] &= 0x1f;
    let inputs: [[u8; 32]; 5] = [*program_vkey_hash, digest, exit_code, vk_root, nonce];

    let key = Groth16Verifyingkey {
        nr_pubinputs: 5,
        vk_alpha_g1: vk::VK_ALPHA_G1,
        vk_beta_g2: vk::VK_BETA_G2,
        vk_gamme_g2: vk::VK_GAMMA_G2,
        vk_delta_g2: vk::VK_DELTA_G2,
        vk_ic: &vk::VK_IC,
    };
    let mut v = Groth16Verifier::new(&a, &b, &c, &inputs, &key).map_err(|_| Error::Proof)?;
    v.verify().map_err(|_| Error::Proof)
}

/// Decodes the 188-byte public values of the chain program.
pub fn decode_chain_summary(values: &[u8]) -> Result<ChainSummary, Error> {
    if values.len() != CHAIN_VALUES_LEN {
        return Err(Error::Length);
    }
    let u64_at = |o: usize| u64::from_le_bytes(field(values, o));
    Ok(ChainSummary {
        block_vkey: field(values, 0),
        start: field(values, 32),
        end: field(values, 64),
        blocks: u32::from_le_bytes(field(values, 96)),
        inputs_hash: field(values, 100),
        results_hash: field(values, 132),
        inputs: u64_at(164),
        results: u64_at(172),
        volume: u64_at(180),
    })
}

/// Verifies a chain proof of the program fixed in `vk::PROGRAM_VKEY_HASH` and returns its summary.
pub fn verify_chain_proof(proof: &[u8], values: &[u8]) -> Result<ChainSummary, Error> {
    if proof.len() != PROOF_LEN || values.len() != CHAIN_VALUES_LEN {
        return Err(Error::Length);
    }
    verify_sp1_groth16(proof, values, &vk::PROGRAM_VKEY_HASH)?;
    decode_chain_summary(values)
}

#[cfg(not(feature = "no-entrypoint"))]
mod entry {
    use super::*;
    use solana_program::{
        account_info::AccountInfo, entrypoint, entrypoint::ProgramResult, log::sol_log_data, msg,
        program_error::ProgramError, pubkey::Pubkey,
    };

    entrypoint!(process);

    fn process(_program_id: &Pubkey, _accounts: &[AccountInfo], data: &[u8]) -> ProgramResult {
        if data.len() != PROOF_LEN + CHAIN_VALUES_LEN {
            return Err(ProgramError::Custom(Error::Length as u32));
        }
        let (proof, values) = data.split_at(PROOF_LEN);
        match verify_chain_proof(proof, values) {
            Ok(s) => {
                msg!(
                    "SP1 chain proof VALID: {} blocks, {} inputs, {} results, volume {}",
                    s.blocks,
                    s.inputs,
                    s.results,
                    s.volume
                );
                // Start and end of the chain as log data (for anchoring)
                sol_log_data(&[&s.start, &s.end]);
                Ok(())
            }
            Err(e) => {
                msg!("SP1 chain proof INVALID: {:?}", e);
                Err(ProgramError::Custom(e as u32))
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn data() -> (Vec<u8>, Vec<u8>) {
        let d = concat!(env!("CARGO_MANIFEST_DIR"), "/../data/");
        (
            std::fs::read(format!("{d}chain_proof.bin")).unwrap(),
            std::fs::read(format!("{d}chain_public_values.bin")).unwrap(),
        )
    }

    #[test]
    fn real_proof_is_valid() {
        let (p, v) = data();
        let s = verify_chain_proof(&p, &v).expect("proof must be valid");
        assert_eq!(s.blocks, 10);
        assert_eq!(s.inputs, 100_000);
        assert_eq!(s.results, 42_757);
        assert_eq!(s.volume, 824_932);
        assert_eq!(s.start[..4], [0x1d, 0xfd, 0x71, 0xe5]);
        assert_eq!(s.end[..4], [0xcc, 0xbd, 0xa9, 0xa9]);
    }

    #[test]
    fn same_result_as_sp1_verifier() {
        let (p, v) = data();
        let h = "0x00f105b29a1590c78dee519677bcfec290c4e83579dc00d8fa80aea0e0fc16ee";
        sp1_verifier::Groth16Verifier::verify(&p, &v, h, &sp1_verifier::GROTH16_VK_BYTES).expect("sp1-verifier");
    }

    #[test]
    fn tampered_volume_rejected() {
        let (p, mut v) = data();
        v[180] ^= 1; // change volume by 1
        assert_eq!(verify_chain_proof(&p, &v), Err(Error::Proof));
    }

    #[test]
    fn tampered_proof_rejected() {
        let (mut p, v) = data();
        p[200] ^= 1;
        assert!(verify_chain_proof(&p, &v).is_err());
    }

    #[test]
    fn wrong_prefix_and_length() {
        let (mut p, v) = data();
        assert_eq!(verify_chain_proof(&p[..355], &v), Err(Error::Length));
        p[0] ^= 1;
        assert_eq!(verify_chain_proof(&p, &v), Err(Error::VkPrefix));
    }

    #[test]
    fn wrong_program_vkey_rejected() {
        let (p, v) = data();
        let mut other = vk::PROGRAM_VKEY_HASH;
        other[31] ^= 1;
        assert_eq!(verify_sp1_groth16(&p, &v, &other), Err(Error::Proof));
        assert_eq!(verify_sp1_groth16(&p, &v, &vk::PROGRAM_VKEY_HASH), Ok(()));
    }
}
